<section class="card" x-data="{ query: '', options: [], selected: '', error: '', controller: null, async search() { this.error=''; this.controller?.abort(); this.controller=new AbortController(); try { const response=await fetch('/admin/sites/{{ $site->id }}/keyword-options?q='+encodeURIComponent(this.query), {signal:this.controller.signal,headers:{Accept:'application/json'}}); if (!response.ok) throw new Error(); this.options=(await response.json()).data; } catch (e) { if (e.name !== 'AbortError') this.error='Chưa tải được keyword. Hãy thử lại.'; } } }" x-init="search()">
    <h2>Giới hạn keyword riêng cho website</h2><p class="muted">Mặc định lấy giới hạn mỗi website từ keyword. Trống là không giới hạn; chọn kế thừa để gỡ giới hạn riêng.</p>
    <label>Tìm keyword<input x-model="query" @input.debounce.300ms="search()" maxlength="100" placeholder="Nhập từ cần tìm"></label><p class="note" x-show="error" x-text="error" x-cloak></p>
    <form method="post" action="/admin/sites/{{ $site->id }}/keyword-limits">@csrf<input type="hidden" name="site_config_epoch" value="{{ $site->config_epoch }}">
        <label>Keyword<select name="keyword_id" x-model="selected" required><option value="">Chọn keyword</option><template x-for="keyword in options" :key="keyword.id"><option :value="keyword.id" x-text="keyword.original_text+' · '+keyword.role"></option></template></select></label>
        <div class="formrow"><label>Số trang tối đa<input name="max_active_pages" type="number" min="0"></label><label class="checkboxline"><input name="inherit" type="checkbox" value="1">Kế thừa giới hạn mặc định</label></div><button class="secondary">Lưu giới hạn website</button>
    </form>
    @if($websiteKeywordLimits->isNotEmpty())<div class="tablewrap"><table><thead><tr><th>Keyword</th><th>Giới hạn riêng</th><th>Mặc định</th><th>Kế thừa</th></tr></thead><tbody>
        @foreach($websiteKeywordLimits as $limit)<tr><td>{{ $limit->original_text }}</td><td>{{ $limit->max_active_pages ?? 'Không giới hạn' }}</td><td>{{ $limit->default_max_active_pages ?? 'Không giới hạn' }}</td><td><form method="post" action="/admin/sites/{{ $site->id }}/keyword-limits">@csrf<input type="hidden" name="site_config_epoch" value="{{ $site->config_epoch }}"><input type="hidden" name="keyword_id" value="{{ $limit->keyword_id }}"><input type="hidden" name="inherit" value="1"><button class="secondary">Gỡ giới hạn riêng</button></form></td></tr>@endforeach
    </tbody></table></div>@endif
</section>
